CREATE TRIGGER IF NOT EXISTS search_documents_card_insert AFTER INSERT ON turn_cards WHEN NEW.card IS NOT NULL BEGIN DELETE FROM search_documents WHERE doc_id IN (SELECT d.doc_id FROM (SELECT NEW.project_id AS project_id, NEW.session_id AS session_id, NEW.turn_key AS turn_key) k CROSS JOIN search_documents d ON d.project_id = k.project_id AND d.kind = 'card' AND d.source_key = json_array(k.session_id, k.turn_key)) AND doc_id NOT IN (SELECT d.doc_id FROM (SELECT NEW.project_id AS project_id, NEW.session_id AS session_id, NEW.turn_key AS turn_key) k CROSS JOIN turn_cards s ON s.project_id = k.project_id AND s.session_id = k.session_id AND s.turn_key = k.turn_key CROSS JOIN search_documents d ON d.project_id = s.project_id AND d.kind = 'card' AND d.source_key = json_array(s.session_id, s.turn_key) WHERE s.card IS NOT NULL AND CAST(MAX(s.created_at, 0) AS INTEGER) = d.record_at AND s.session_id IS d.session_id); UPDATE search_documents SET (facets, headline, body) = (SELECT 'p' || lower(hex(s.project_id)) || ' kcard ' || 's' || lower(hex(s.session_id)), s.headline, s.card FROM turn_cards s WHERE s.project_id = search_documents.project_id AND s.session_id = search_documents.session_id AND s.turn_key = json_extract(search_documents.source_key, '$[1]')) WHERE doc_id IN (SELECT d.doc_id FROM (SELECT NEW.project_id AS project_id, NEW.session_id AS session_id, NEW.turn_key AS turn_key) k CROSS JOIN search_documents d ON d.project_id = k.project_id AND d.kind = 'card' AND d.source_key = json_array(k.session_id, k.turn_key)) AND (facets, headline, body) IS NOT (SELECT 'p' || lower(hex(s.project_id)) || ' kcard ' || 's' || lower(hex(s.session_id)), s.headline, s.card FROM turn_cards s WHERE s.project_id = search_documents.project_id AND s.session_id = search_documents.session_id AND s.turn_key = json_extract(search_documents.source_key, '$[1]')); INSERT INTO search_documents(doc_id, project_id, kind, source_key, session_id, record_at, facets, headline, body) SELECT COALESCE((SELECT MAX(x.doc_id) + 1 FROM search_documents x WHERE x.doc_id >= (CAST(c.ms AS INTEGER) / 1000) * 1048576 AND x.doc_id < ((CAST(c.ms AS INTEGER) / 1000) + 1) * 1048576), (CAST(c.ms AS INTEGER) / 1000) * 1048576) + ROW_NUMBER() OVER (PARTITION BY c.ms / 1000 ORDER BY c.source_key) - 1, c.project_id, 'card', c.source_key, c.session_id, c.ms, c.facets, c.headline, c.body FROM (SELECT s.project_id, json_array(s.session_id, s.turn_key) AS source_key, s.session_id, CAST(MAX(s.created_at, 0) AS INTEGER) AS ms, 'p' || lower(hex(s.project_id)) || ' kcard ' || 's' || lower(hex(s.session_id)) AS facets, s.headline AS headline, s.card AS body FROM (SELECT NEW.project_id AS project_id, NEW.session_id AS session_id, NEW.turn_key AS turn_key) k CROSS JOIN turn_cards s ON s.project_id = k.project_id AND s.session_id = k.session_id AND s.turn_key = k.turn_key WHERE s.card IS NOT NULL AND NOT EXISTS (SELECT 1 FROM search_documents d WHERE d.project_id = s.project_id AND d.kind = 'card' AND d.source_key = json_array(s.session_id, s.turn_key))) c WHERE 1; END;

CREATE TRIGGER IF NOT EXISTS search_documents_card_update AFTER UPDATE OF project_id, session_id, turn_key, card, headline, created_at ON turn_cards WHEN (OLD.project_id IS NOT NEW.project_id OR OLD.session_id IS NOT NEW.session_id OR OLD.turn_key IS NOT NEW.turn_key OR OLD.card IS NOT NEW.card OR OLD.headline IS NOT NEW.headline OR OLD.created_at IS NOT NEW.created_at) AND (OLD.card IS NOT NULL OR NEW.card IS NOT NULL) BEGIN DELETE FROM search_documents WHERE doc_id IN (SELECT d.doc_id FROM (SELECT OLD.project_id AS project_id, OLD.session_id AS session_id, OLD.turn_key AS turn_key UNION SELECT NEW.project_id AS project_id, NEW.session_id AS session_id, NEW.turn_key AS turn_key) k CROSS JOIN search_documents d ON d.project_id = k.project_id AND d.kind = 'card' AND d.source_key = json_array(k.session_id, k.turn_key)) AND doc_id NOT IN (SELECT d.doc_id FROM (SELECT OLD.project_id AS project_id, OLD.session_id AS session_id, OLD.turn_key AS turn_key UNION SELECT NEW.project_id AS project_id, NEW.session_id AS session_id, NEW.turn_key AS turn_key) k CROSS JOIN turn_cards s ON s.project_id = k.project_id AND s.session_id = k.session_id AND s.turn_key = k.turn_key CROSS JOIN search_documents d ON d.project_id = s.project_id AND d.kind = 'card' AND d.source_key = json_array(s.session_id, s.turn_key) WHERE s.card IS NOT NULL AND CAST(MAX(s.created_at, 0) AS INTEGER) = d.record_at AND s.session_id IS d.session_id); UPDATE search_documents SET (facets, headline, body) = (SELECT 'p' || lower(hex(s.project_id)) || ' kcard ' || 's' || lower(hex(s.session_id)), s.headline, s.card FROM turn_cards s WHERE s.project_id = search_documents.project_id AND s.session_id = search_documents.session_id AND s.turn_key = json_extract(search_documents.source_key, '$[1]')) WHERE doc_id IN (SELECT d.doc_id FROM (SELECT OLD.project_id AS project_id, OLD.session_id AS session_id, OLD.turn_key AS turn_key UNION SELECT NEW.project_id AS project_id, NEW.session_id AS session_id, NEW.turn_key AS turn_key) k CROSS JOIN search_documents d ON d.project_id = k.project_id AND d.kind = 'card' AND d.source_key = json_array(k.session_id, k.turn_key)) AND (facets, headline, body) IS NOT (SELECT 'p' || lower(hex(s.project_id)) || ' kcard ' || 's' || lower(hex(s.session_id)), s.headline, s.card FROM turn_cards s WHERE s.project_id = search_documents.project_id AND s.session_id = search_documents.session_id AND s.turn_key = json_extract(search_documents.source_key, '$[1]')); INSERT INTO search_documents(doc_id, project_id, kind, source_key, session_id, record_at, facets, headline, body) SELECT COALESCE((SELECT MAX(x.doc_id) + 1 FROM search_documents x WHERE x.doc_id >= (CAST(c.ms AS INTEGER) / 1000) * 1048576 AND x.doc_id < ((CAST(c.ms AS INTEGER) / 1000) + 1) * 1048576), (CAST(c.ms AS INTEGER) / 1000) * 1048576) + ROW_NUMBER() OVER (PARTITION BY c.ms / 1000 ORDER BY c.source_key) - 1, c.project_id, 'card', c.source_key, c.session_id, c.ms, c.facets, c.headline, c.body FROM (SELECT s.project_id, json_array(s.session_id, s.turn_key) AS source_key, s.session_id, CAST(MAX(s.created_at, 0) AS INTEGER) AS ms, 'p' || lower(hex(s.project_id)) || ' kcard ' || 's' || lower(hex(s.session_id)) AS facets, s.headline AS headline, s.card AS body FROM (SELECT OLD.project_id AS project_id, OLD.session_id AS session_id, OLD.turn_key AS turn_key UNION SELECT NEW.project_id AS project_id, NEW.session_id AS session_id, NEW.turn_key AS turn_key) k CROSS JOIN turn_cards s ON s.project_id = k.project_id AND s.session_id = k.session_id AND s.turn_key = k.turn_key WHERE s.card IS NOT NULL AND NOT EXISTS (SELECT 1 FROM search_documents d WHERE d.project_id = s.project_id AND d.kind = 'card' AND d.source_key = json_array(s.session_id, s.turn_key))) c WHERE 1; END;

