ECT MAX(x.doc_id) + 1 FROM search_documents x WHERE x.doc_id >= (CAST(c.ms AS INTEGER) / 1000) * 1048576 AND x.doc_id < ((CAST(c.ms AS INTEGER) / 1000) + 1) * 1048576), (CAST(c.ms AS INTEGER) / 1000) * 1048576) + ROW_NUMBER() OVER (PARTITION BY c.ms / 1000 ORDER BY c.source_key) - 1, c.project_id, 'card', c.source_key, c.session_id, c.ms, c.facets, c.headline, c.body FROM (SELECT s.project_id, json_array(s.session_id, s.turn_key) AS source_key, s.session_id, CAST(MAX(s.created_at, 0) AS INTEGER) AS ms, 'p' || lower(hex(s.project_id)) || ' kcard ' || 's' || lower(hex(s.session_id)) AS facets, s.headline AS headline, s.card AS body FROM (SELECT OLD.project_id AS project_id, OLD.session_id AS session_id, OLD.turn_key AS turn_key) k CROSS JOIN turn_cards s ON s.project_id = k.project_id AND s.session_id = k.session_id AND s.turn_key = k.turn_key WHERE s.card IS NOT NULL AND NOT EXISTS (SELECT 1 FROM search_documents d WHERE d.project_id = s.project_id AND d.kind = 'card' AND d.source_key = json_array(s.session_id, s.turn_key))) c WHERE 1; END;

INSERT INTO projection_catchup(projection, phase, done) SELECT 'search_documents', 'searchSessions', NOT EXISTS (SELECT 1 FROM sessions);

INSERT INTO projection_catchup(projection, phase, done) SELECT 'search_documents', 'searchPlans', NOT EXISTS (SELECT 1 FROM plans);

INSERT INTO projection_catchup(projection, phase, done) SELECT 'search_documents', 'searchSpores', NOT EXISTS (SELECT 1 FROM spores);

INSERT INTO projection_catchup(projection, phase, done) SELECT 'search_documents', 'searchCards', NOT EXISTS (SELECT 1 FROM turn_cards);

CREATE TABLE IF NOT EXISTS search_blob_refs(project_id TEXT NOT NULL CHECK (project_id NOT GLOB '*[^A-Za-z0-9._-]*' AND length(project_id) BETWEEN 1 AND 64 AND project_id NOT IN ('.', '..')), plan_key TEXT NOT NULL, blob_key TEXT NOT NULL, PRIMARY KEY(project_id, plan_key)) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS idx_search_blob_refs_blob ON search_blob_refs(project_id, blob_key);

CREATE TABLE IF NOT EXISTS search_blobs(project_id TEXT NOT NULL CHECK (project_id NOT GLOB '*[^A-Za-z0-9._-]*' AND length(project_id) BETWEEN 1 AND 64 AND project_id NOT IN ('.', '..')), blob_key TEXT NOT NULL, live_refs INTEGER NOT NULL CHECK (live_refs >= 0), state TEXT NOT NULL CHECK (state IN ('pending','indexed','retiring')), generation INTEGER NOT NULL DEFAULT 0, claim INTEGER NOT NULL DEFAULT 0, next_byte INTEGER NOT NULL DEFAULT 0, due_at INTEGER NOT NULL DEFAULT 0, pending_since INTEGER, failures INTEGER NOT NULL DEFAULT 0, failure TEXT, PRIMARY KEY(project_id, blob_key)) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS idx_search_blobs_due ON search_blobs(due_at, project_id, blob_key) WHERE state <> 'indexed';

CREATE INDEX IF NOT EXISTS idx_search_blobs_waiting ON search_blobs(pending_since) WHERE state = 'pending';

CREATE TABLE IF NOT EXISTS search_index_status(project_id TEXT NOT NULL PRIMARY KEY CHECK (project_id NOT GLOB '*[^A-Za-z0-9._-]*' AND length(project_id) BETWEEN 1 AND 64 AND project_id NOT IN ('.', '..')), pending INTEGER NOT NULL) WITHOUT ROWID;

CREATE TRIGGER IF NOT EXISTS search_blob_refs_plan_insert AFTER INSERT ON plans WHEN NEW.blob_key IS NOT NULL BEGIN DELETE FROM search_blob_refs WHERE (project_id, plan_key) IN (SELECT project_id, plan_key FROM (SELECT NEW.project_id AS project_id, NEW.plan_key AS plan_key)) AND NOT EXISTS (SELECT 1 FROM plans p WHERE p.project_id = search_blob_refs.project_id AND p.plan_key = search_blob_refs.plan_key AND p.blob_key = search_blob_refs.blob_key AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed')); INSERT INTO search_blob_refs(project_id, plan_key, blob_key) SELECT p.project_id, p.plan_key, p.blob_key FROM (SELECT NEW.project_id AS project_id, NEW.plan_key AS plan_key) k CROSS JOIN plans p ON p.project_id = k.project_id AND p.plan_key = k.plan_key WHERE p.blob_key IS NOT NULL AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed') ON CONFLICT(project_id, plan_key) DO NOTHING; END;

CREATE TRIGGER IF NOT EXISTS search_blob_refs_plan_update AFTER UPDATE OF project_id, plan_key, blob_key ON plans WHEN OLD.project_id IS NOT NEW.project_id OR OLD.plan_key IS NOT NEW.plan_key OR OLD.blob_key IS NOT NEW.blob_key BEGIN DELETE FROM search_blob_refs WHERE (project_id, plan_key) IN (SELECT project_id, plan_key FROM (SELECT OLD.project_id AS project_id, OLD.plan_key AS plan_key UNION SELECT NEW.project_id AS project_id, NEW.plan_key AS plan_key)) AND NOT EXISTS (SELECT 1 FROM plans p WHERE p.project_id = search_blob_refs.project_id AND p.plan_key = search_blob_refs.plan_key AND p.blob_key = search_blob_refs.blob_key AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed')); INSERT INTO search_blob_refs(project_id, plan_key, blob_key) SELECT p.project_id, p.plan_key, p.blob_key FROM (SELECT OLD.project_id AS project_id, OLD.plan_key AS plan_key UNION SELECT NEW.project_id AS project_id, NEW.plan_key AS plan_key) k CROSS JOIN plans p ON p.project_id = k.project_id AND p.plan_key = k.plan_key WHERE p.blob_key IS NOT NULL AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed') ON CONFLICT(project_id, plan_key) DO NOTHING; END;

CREATE TRIGGER IF NOT EXISTS search_blob_refs_plan_delete AFTER DELETE ON plans WHEN OLD.blob_key IS NOT NULL BEGIN DELETE FROM search_blob_refs WHERE (project_id, plan_key) IN (SELECT project_id, plan_key FROM (SELECT OLD.project_id AS project_id, OLD.plan_key AS plan_key)) AND NOT EXISTS (SELECT 1 FROM plans p WHERE p.project_id = search_blob_refs.project_id AND p.plan_key = search_blob_refs.plan_key AND p.blob_key = search_blob_refs.blob_key AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed')); INSERT INTO search_blob_refs(project_id, plan_key, blob_key) SELECT p.project_id, p.plan_key, p.blob_key FROM (SELECT OLD.project_id AS project_id, OLD.plan_key AS plan_key) k CROSS JOIN plans p ON p.project_id = k.project_id AND p.plan_key = k.plan_key WHERE p.blob_key IS NOT NULL AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed') ON CONFLICT(project_id, plan_key) DO NOTHING; END;

CREATE TRIGGER IF NOT EXISTS search_blob_refs_proof_insert AFTER INSERT ON processed_resources WHEN NEW.kind = 'plan' BEGIN DELETE FROM search_blob_refs WHERE (project_id, plan_key) IN (SELECT project_id, plan_key FROM (SELECT NEW.project_id AS project_id, NEW.resource_id AS plan_key)) AND NOT EXISTS (SELECT 1 FROM plans p WHERE p.project_id = search_blob_refs.project_id AND p.plan_key = search_blob_refs.plan_key AND p.blob_key = search_blob_refs.blob_key AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed')); INSERT INTO search_blob_refs(project_id, plan_key, blob_key) SELECT p.project_id, p.plan_key, p.blob_key FROM (SELECT NEW.project_id AS project_id, NEW.resource_id AS plan_key) k CROSS JOIN plans p ON p.project_id = k.project_id AND p.plan_key = k.plan_key WHERE p.blob_key IS NOT NULL AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed') ON CONFLICT(project_id, plan_key) DO NOTHING; END;

CREATE TRIGGER IF NOT EXISTS search_blob_refs_proof_update AFTER UPDATE OF project_id, kind, resource_id, blob_key, classification ON processed_resources WHEN (OLD.kind = 'plan' OR NEW.kind = 'plan') AND (OLD.project_id IS NOT NEW.project_id OR OLD.kind IS NOT NEW.kind OR OLD.resource_id IS NOT NEW.resource_id OR OLD.blob_key IS NOT NEW.blob_key OR OLD.classification IS NOT NEW.classification) BEGIN DELETE FROM search_blob_refs WHERE (project_id, plan_key) IN (SELECT project_id, plan_key FROM (SELECT OLD.project_id AS project_id, OLD.resource_id AS plan_key UNION SELECT NEW.project_id AS project_id, NEW.resource_id AS plan_key)) AND NOT EXISTS (SELECT 1 FROM plans p WHERE p.project_id = search_blob_refs.project_id AND p.plan_key = search_blob_refs.plan_key AND p.blob_key = search_blob_refs.blob_key AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed')); INSERT INTO search_blob_refs(project_id, plan_key, blob_key) SELECT p.project_id, p.plan_key, p.blob_key FROM (SELECT OLD.project_id AS project_id, OLD.resource_id AS plan_key UNION SELECT NEW.project_id AS project_id, NEW.resource_id AS plan_key) k CROSS JOIN plans p ON p.project_id = k.project_id AND p.plan_key = k.plan_key WHERE p.blob_key IS NOT NULL AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed') ON CONFLICT(project_id, plan_key) DO NOTHING; END;

CREATE TRIGGER IF NOT EXISTS search_blob_refs_proof_delete AFTER DELETE ON processed_resources WHEN OLD.kind = 'plan' BEGIN DELETE FROM search_blob_refs WHERE (project_id, plan_key) IN (SELECT project_id, plan_key FROM (SELECT OLD.project_id AS project_id, OLD.resource_id AS plan_key)) AND NOT EXISTS (SELECT 1 FROM plans p WHERE p.project_id = search_blob_refs.project_id AND p.plan_key = search_blob_refs.plan_key AND p.blob_key = search_blob_refs.blob_key AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed')); INSERT INTO search_blob_refs(project_id, plan_key, blob_key) SELECT p.project_id, p.plan_key, p.blob_key FROM (SELECT OLD.project_id AS project_id, OLD.resource_id AS plan_key) k CROSS JOIN plans p ON p.project_id = k.project_id AND p.plan_key = k.plan_key WHERE p.blob_key IS NOT NULL AND EXISTS ( SELECT 1 FROM processed_resources pr WHERE pr.project_id = p.project_id AND pr.kind = 'plan' AND pr.resource_id = p.plan_key AND pr.blob_key = p.blob_key AND pr.classification = 'processed') ON CONFLICT(project_id, plan_key) DO NOTHING; END;

CREATE TRIGGER IF NOT EXISTS search_blob_refs_insert AFTER INSERT ON search_blob_refs BEGIN INSERT INTO search_blobs(project_id, blob_key, live_refs, state, generation, next_byte, due_at, pending_since) VALUES (NEW.project_id, NEW.blob_key, 1, 'pending', 0, 0, 0, COALESCE((SELECT received_at FROM blobs WHERE project_id = NEW.project_id AND key = NEW.blob_key), CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))) ON CONFLICT(project_id, blob_key) DO UPDATE SET live_refs = live_refs + 1, next_byte = CASE WHEN state = 'retiring' THEN 0 ELSE next_byte END, generation = CASE WHEN state = 'retiring' THEN generation + 1 ELSE generation END, due_at = CASE WHEN state = 'retiring' THEN 0 ELSE due_at END, pending_since = CASE WHEN state = 'retiring' THEN CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER) ELSE pending_since END, state = CASE WHEN state = 'retiring' THEN 'pending' ELSE state END; END;

CREATE TRIGGER IF NOT EXISTS search_blob_refs_delete AFTER DELETE ON search_blob_refs BEGIN UPDATE search_blobs SET live_refs = live_refs - 1, generation = CASE WHEN live_refs = 1 THEN generation + 1 ELSE generation END, due_at = CASE WHEN live_refs = 1 THEN 0 ELSE due_at END, state = CASE WHEN live_refs = 1 THEN 'retiring' ELSE state END WHERE project_id = OLD.project_id AND blob_key = OLD.blob_key; END;

CREATE TRIGGER IF NOT EXISTS search_blobs_count_insert AFTER INSERT ON search_blobs BEGIN INSERT INTO search_index_status(project_id, pending) VALUES (NEW.project_id, NEW.state = 'pending') ON CONFLICT(project_id) DO UPDATE SET pending = pending + (NEW.state = 'pending'); END;

CREATE TRIGGER IF NOT EXISTS search_blobs_count_update AFTER UPDATE OF state ON search_blobs WHEN OLD.state IS NOT NEW.state BEGIN INSERT INTO search_index_status(project_id, pending) VALUES (NEW.project_id, (NEW.state = 'pending') - (OLD.state = 'pending')) ON CONFLICT(project_id) DO UPDATE SET pending = pending + ((NEW.state = 'pending') - (OLD.state = 'pending')); END;

CREATE TRIGGER IF NOT EXISTS search_blobs_count_delete AFTER DELETE ON search_blobs BEGIN INSERT INTO search_index_status(project_id, pending) VALUES (OLD.project_id, -(OLD.state = 'pending')) ON CONFLICT(project_id) DO UPDATE SET pending = pending + (-(OLD.state = 'pending')); END;

INSERT INTO projection_catchup(projection, phase, done) SELECT 'search_documents', 'searchBlobRefs', NOT EXISTS (SELECT 1 FROM plans);

CREATE TABLE IF NOT EXISTS search_result_windows(search_id TEXT NOT NULL PRIMARY KEY, reader TEXT NOT NULL, binding TEXT NOT NULL, asof INTEGER NOT NULL, expires_at INTEGER NOT NULL, round INTEGER NOT NULL, kinds TEXT NOT NULL, hits TEXT NOT NULL) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS idx_search_result_windows_expiry ON search_result_windows(expires_at, search_id);

CREATE INDEX IF NOT EXISTS idx_search_result_windows_reader ON search_result_windows(reader, expires_at);

